TYPE.TEST:


SetFunctionName("DegToRad");
Validate( IsEqualWithEpsilon(DegToRad(Soa4FloatFromFloat(180.0f)), Soa4FloatFromFloat(::rw::math::fpu::PI)) );
Validate( IsEqualWithEpsilon(DegToRad(Soa4FloatFromFloat(360.0f)), Soa4FloatFromFloat(::rw::math::fpu::TWO_PI)) );
Validate( IsEqualWithEpsilon(DegToRad(Soa4FloatFromFloat(0.0f)), Soa4FloatFromFloat(0.0f)) );



        SetFunctionName("RadToDeg");
        Validate(IsEqualWithEpsilon(RadToDeg(Soa4FloatFromFloat(0.0f)), Soa4FloatFromFloat(0.f), Soa4FloatFromFloat(::rw::math::fpu::SMALL_FLOAT)));

#if defined EA_PLATFORM_PS3_SPU        

        Validate(IsEqualWithinPercent(RadToDeg(Soa4FloatFromFloat(::rw::math::fpu::PI)), Soa4FloatFromFloat(180.f), Soa4FloatFromFloat(0.0001)));
        Validate(IsEqualWithinPercent(RadToDeg(Soa4FloatFromFloat(::rw::math::fpu::TWO_PI)), Soa4FloatFromFloat(360.f), Soa4FloatFromFloat(0.0001)));
#else
        Validate(IsEqualWithEpsilon(RadToDeg(Soa4FloatFromFloat(::rw::math::fpu::PI)), Soa4FloatFromFloat(180.f), Soa4FloatFromFloat(::rw::math::fpu::SMALL_FLOAT)));
        Validate(IsEqualWithEpsilon(RadToDeg(Soa4FloatFromFloat(::rw::math::fpu::TWO_PI)), Soa4FloatFromFloat(360.f), Soa4FloatFromFloat(::rw::math::fpu::SMALL_FLOAT)));
#endif



SetFunctionName("Sin test");
bool success = true;
for (int i = 0; i < NUM_SINCOS_VALUES; ++i)
{
    success &= IsEqualWithEpsilon(Sin(Soa4FloatFromFloat(sincos_values[i].input)),
        Soa4FloatFromFloat(sincos_values[i].output1), Soa4FloatFromFloat(FSIN_EPSILON));
}
Validate(success);



