}
Validate(success);



SetFunctionName("ATan2 test");
bool success = true;
for (int i = 0; i < NUM_ATAN2_VALUES; ++i)
{
    Soa4Float atan2Result = ATan2(Soa4FloatFromFloat(atan2_values[i].x), Soa4FloatFromFloat(atan2_values[i].y));
    bool result = IsEqualWithEpsilon(atan2Result, Soa4FloatFromFloat(atan2_values[i].output), Soa4FloatFromFloat(FATAN_EPSILON));
    // Special case:  PI and -PI should be considered equally valid.
    if( atan2_values[i].output == -3.141593f && !result )
    {
        result = IsEqualWithEpsilon(atan2Result, Soa4FloatFromFloat(3.141593f), Soa4FloatFromFloat(FATAN_EPSILON));
    }
    success &= result;
}
Validate(success);



        SetFunctionName("NormalizeAngle");
        bool success = true;
        success &= IsEqualWithEpsilon(NormalizeAngle(Soa4FloatFromFloat(::rw::math::fpu::TWO_PI + 1.1f)), Soa4FloatFromFloat(1.1f));
	    success &= IsEqualWithEpsilon(NormalizeAngle( Soa4FloatFromFloat(::rw::math::fpu::QUARTER_PI)),  Soa4FloatFromFloat(::rw::math::fpu::QUARTER_PI));
	    success &= IsEqualWithEpsilon(NormalizeAngle(Soa4FloatFromFloat(-::rw::math::fpu::QUARTER_PI)), Soa4FloatFromFloat(-::rw::math::fpu::QUARTER_PI));
	    success &= IsEqualWithEpsilon(NormalizeAngle(Soa4FloatFromFloat(::rw::math::fpu::PI + 0.1f)), Soa4FloatFromFloat(-::rw::math::fpu::PI + 0.1f));
	    success &= IsEqualWithEpsilon(NormalizeAngle(Soa4FloatFromFloat(-::rw::math::fpu::PI + 0.1f)), Soa4FloatFromFloat(-::rw::math::fpu::PI + 0.1f));
	    success &= IsEqualWithEpsilon(NormalizeAngle(Soa4FloatFromFloat(0.f)), Soa4FloatFromFloat(0.f));
	    success &= IsEqualWithEpsilon(NormalizeAngle(Soa4FloatFromFloat(::rw::math::fpu::TWO_PI)), Soa4FloatFromFloat(0.f));
	    success &= IsEqualWithEpsilon(NormalizeAngle(Soa4FloatFromFloat(-::rw::math::fpu::PI - 0.1f)), Soa4FloatFromFloat(::rw::math::fpu::PI - 0.1f));
        Validate(success);



Soa4Float fSin, fCos;

bool success = true;
for (int i = 0; i < NUM_SINCOS_VALUES; ++i)
{
    SetFunctionName("SinCos(a, sin_out, cos_out)");
    SinCos(Soa4FloatFromFloat(sincos_values[i].input), fSin, fCos);

    success &= IsEqualWithEpsilon( fSin, Soa4FloatFromFloat(sincos_values[i].output1), Soa4FloatFromFloat(FSINCOS_EPSILON) );
    success &= IsEqualWithEpsilon( fCos, Soa4FloatFromFloat(sincos_values[i].output2), Soa4FloatFromFloat(FSINCOS_EPSILON) );
}
Validate(success);


